import { INDEX_FORMAT, WORKSPACE_FORMAT } from "./format-version";

/**
 * The files EngineCV writes into a workspace so an agent can work in it without guessing: a short
 * instruction file, a human README, and the machine-area marker files. English on purpose (agents),
 * the person's own documents keep their language. Reference files and recipes are added in the
 * agent-efficiency story; this first version covers setup.
 */

export const AGENTS_FILE = "AGENTS.md";
export const README_FILE = "README.md";
export const MACHINE_DIR = ".enginecv";

/** First line of generated files, so a file the person edited is never overwritten (research R11). */
export const GENERATED_MARK = "<!-- generated by EngineCV; edit freely, EngineCV will not overwrite a changed copy -->";

export function agentsMarkdown(): string {
    return `${GENERATED_MARK}
# EngineCV workspace

This folder mirrors EngineCV CVs and cover letters as plain JSON files. EngineCV (open in a browser tab) reads every change you save here.

Start with \`.enginecv/index.json\`, then open only the file you need.
- CVs: \`cvs/*.cv.json\`
- Letters: \`letters/*.letter.json\`

Rules
1. Change only what was asked. Keep \`id\`, \`format\` and every entry you were not asked to touch.
2. Save the whole file in one write. Never leave it half written.
3. Do not remove many entries or whole sections unless told to. EngineCV holds such a change for review.
4. A letter with \`"status": "sent"\` is frozen. To reuse it, write a new letter file with a new \`id\`.
5. Do not edit \`exports/\` or \`.enginecv/\`, except request files.
6. If EngineCV refuses a change, read \`.enginecv/results/\` and \`.enginecv/log.ndjson\`, fix the file and save again.

Read more only when needed
- \`.enginecv/reference/cv-format.md\`: CV fields
- \`.enginecv/reference/letter-format.md\`: letters
- \`.enginecv/reference/exports.md\`: exports and PDFs
- \`.enginecv/reference/recipes.md\`: worked examples
`;
}

export function readmeMarkdown(): string {
    return `${GENERATED_MARK}
# EngineCV workspace folder

EngineCV keeps your CVs and cover letters in this folder as readable files, so you can back them up, put them under version control or let an AI agent edit them.

- \`cvs/\` one file per CV, \`letters/\` one file per cover letter
- \`exports/\` files EngineCV writes when asked (PDF, Word and so on)
- \`.enginecv/\` machine files EngineCV maintains; \`.enginecv/.gitignore\` keeps the noisy ones out of git
- \`AGENTS.md\` the short instructions an agent reads first

These files contain your personal details (name, email, phone, address) unless you chose to leave contact details out. If this folder is in a repository or a cloud folder, those services can see them.

The files stay on your computer. EngineCV never uploads them.
`;
}

export function workspaceJson(input: { id: string; createdAt: number; appVersion: string; hideContact: boolean }): string {
    return `${JSON.stringify({ format: WORKSPACE_FORMAT, id: input.id, createdAt: new Date(input.createdAt).toISOString(), appVersion: input.appVersion, hideContact: input.hideContact }, null, 2)}\n`;
}

/** Keeps the machine area's transient files out of version control (the setup also writes this file). */
export function machineGitignore(): string {
    return "requests/\nresults/\nconflicts/\nlog.ndjson\n";
}

export { INDEX_FORMAT };
